import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.DfDAiEgj.js";const l="/2bPM/img/2bPM.png",h="/2bPM/img/low_cost2data_traffic.png",i="/2bPM/img/full_stack_PM_skill_tree.png",u=JSON.parse('{"title":"To be AI PM","description":"","frontmatter":{},"headers":[],"relativePath":"home.md","filePath":"home.md","lastUpdated":null}'),n={name:"home.md"};function p(s,a,c,b,f,m){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="to-be-ai-pm" tabindex="-1">To be AI PM <a class="header-anchor" href="#to-be-ai-pm" aria-label="Permalink to &quot;To be AI PM&quot;">​</a></h1><ul><li>背景：传统的招聘方由于求职方是否了解AI产品经理的职位要求以及公司情况而要求简历、设立面试环节（原有解决方案），而由于简历篇幅有限只能展示部分、时间有限往往只能出几个问题，不能确保全面考察到了面试者的能力，而这时求职方往往只有为数不多的时间去应答，极度考验临场反应来对答案进行表述，相比之前的积攒的能力这种情况有很强的随机性。</li><li>动机：为了公司（UCD）能尽快全面了解到我个人的能力，以最快捷最有效地招募到人才（哈哈哈，王婆卖瓜），而写出这本书（此时书即预备产品，我即产品经理<a href="https://mp.weixin.qq.com/s?__biz=MjM5MzE3MDQ3Mw==&amp;mid=2650404998&amp;idx=5&amp;sn=3717d423a70a8b1b860ad6f5a81f4f72&amp;chksm=be964dc089e1c4d6414995b77c3d16cbf616d1302ab86387c822c90c2b42aab8716940b4f82b&amp;scene=21#wechat_redirect" target="_blank" rel="noreferrer">^14</a>）。</li><li>目标用户主要是招聘方，等待您需求的验证！同时可以给一些想一同成为AI金融产品经理的同学（不过你是我的竞品哎）提供参考。</li><li>同时欢迎讨论与反馈<a href="http://www.ramywu.com/work/2018/04/09/How-to-Learn-AI-PM-Tacit-Knowledge/" target="_blank" rel="noreferrer">^6</a>：<a href="https://github.com/StevenJokess/2bPM/issues" target="_blank" rel="noreferrer">https://github.com/StevenJokess/2bPM/issues</a></li></ul><h2 id="成为ai-pm的路径" tabindex="-1">成为AI PM的路径 <a class="header-anchor" href="#成为ai-pm的路径" aria-label="Permalink to &quot;成为AI PM的路径&quot;">​</a></h2><p><img src="'+l+'" alt="成为AI PM"></p><h2 id="产品经理" tabindex="-1">产品经理 <a class="header-anchor" href="#产品经理" aria-label="Permalink to &quot;产品经理&quot;">​</a></h2><p>产品经理是一个技能积累要求高，需要广度的职业， 你不能不了解产品设计，心理学，经济学，技术趋势，财务知识等等。其他职能的技能经验积累会在一个明确的方向内，积累一级的经验可以升一级，产品则需要十个方向十级经验量才能升一级。 <a href="https://zhuanlan.zhihu.com/p/30984881" target="_blank" rel="noreferrer">^3</a></p><p>当下时代，行业和市场的变化异常迅速，每一个行业的模式每个月都在进化，旧模式将无法适用。 假设你今天在金融，或在广告，或在电商，你以为自己以后可以以多年金融产品经验、多年广告产品经验、多年电商经验，可以开始吃老本，工作可以轻松而游刃有余，还是醒醒，不现实，马上被淘汰。</p><p>产品经理是一个停不下来的职业，不论是一直做一个类型的业务，或者不断变换业务，当对手在进化的时候，当行业趋势在改变的时候，你就有一堆东西要从头学起了。</p><p>真的一点安全感都没有吗，那工作中的经历会不会留下什么？会。</p><p>你要给自己搭建一个书库，把每一天，每一份工作遇到的东西，变成你的藏品放在你的书架上。这个书库分门别类，便于你日后查找，你不论遇到什么问题，都能查到资料来应对，反而还会觉得每次做不同的东西特别有乐趣，好挑战。这个书库叫做“知识体系”。</p><p><strong>有了知识体系，有了方法论，才能有资格、有机会去创造那些还未出现的产品形态</strong></p><h2 id="ai产品经理专业体系" tabindex="-1">AI产品经理专业体系 <a class="header-anchor" href="#ai产品经理专业体系" aria-label="Permalink to &quot;AI产品经理专业体系&quot;">​</a></h2><p>没有实际经验，是断无可能获得产品/实验方面的知识的。这种观点，我坚决不认同。虽然我之前并没有任何产品或 A/B 测试的经验，但我相信，这些技能是可以通过阅读、倾听、思考和总结来获得。毕竟，这与我们在学校里接受教育的方式也一样不是？<a href="https://www.infoq.cn/article/IPDVRNxwJVsx3ZGrgwzW" target="_blank" rel="noreferrer">^9</a></p><p>将网络上杂乱的内容进行有效整理（互联网上充斥着各种资源，主动降噪（知识卸载和去重<a href="http://www.woshipm.com/zhichang/4156203.html" target="_blank" rel="noreferrer">^10</a>）来过滤出最优质的内容以飨自己。<a href="https://www.zhihu.com/question/29342383/answer/44323650" target="_blank" rel="noreferrer">^7</a>），用逻辑（从框架到细节、前后顺序）搭建自己的AI产品经理专业体系 <a href="http://www.woshipm.com/zhichang/3945751.html" target="_blank" rel="noreferrer">^1</a></p><p>好处：</p><ul><li>有目的方向的去扩充我的专业库，积累我的经验。</li><li>非常多的信息总结和跟踪，提高我二次工作的效率性。</li><li>使我的积累形成系统化，随时能快速找出信息。</li></ul><p>框架的思考方式避免我们的遗漏，有益于创造一个无错的产品，但是“魔鬼在于细节”，对于细节的<strong>洞察</strong>或许更能打动用户。<a href="https://zhuanlan.zhihu.com/p/34673277" target="_blank" rel="noreferrer">^8</a></p><h3 id="驳斥工作经验论" tabindex="-1">驳斥工作经验论 <a class="header-anchor" href="#驳斥工作经验论" aria-label="Permalink to &quot;驳斥工作经验论&quot;">​</a></h3><p>如果没有对社会、市场和人很好的理解，即便在一个行业有十年、二十年的工作经验，不代表具有产品创新能力。只能说这个人熟悉这个行业，有很好的专业经验或管理经验。<a href="https://www.zhihu.com/question/21867702/answer/32260919" target="_blank" rel="noreferrer">^20</a></p><h3 id="「长期主义」" tabindex="-1">「长期主义」 <a class="header-anchor" href="#「长期主义」" aria-label="Permalink to &quot;「长期主义」&quot;">​</a></h3><p>「长期主义」价值观：用长远的目光分析事物的发展走向，什么能产生更广泛更长期的影响？有且只有一条标准，那就是是否在创造真正的价值，这个价值是否有益于社会的整体繁荣。 <a href="https://zhuanlan.zhihu.com/p/340824405" target="_blank" rel="noreferrer">^17</a></p><p>当下流行的碎片化学习要坚持「长期主义」，在建立个人系统化的知识网络的基础上，有规划地持续不断地学习，进而提高学习质效，满足其个性化的知识需求，完成个人知识管理</p><p>从碎片化的时间里学习到知识 -&gt; 知识体系<a href="https://www.zhihu.com/market/paid_magazine/1153593677761941504/section/1153593764286263296" target="_blank" rel="noreferrer">^16</a></p><p>反对机会主义：为了眼前暂时的利益而忘记根本大计，只图一时的成就而不顾后果，为了目前牺牲未来的运动，这种做法也许是出于“真诚的”动机。但这是机会主义，始终是机会主义，而且“真诚的”机会主义也许比其他一切机会主义更危险。<a href="https://www.bilibili.com/video/BV1gz4y1r7W3?from=search&amp;seid=16897168704938729893" target="_blank" rel="noreferrer">^25</a></p><p>注重眼前利益的人，拼命压榨“价值空间”，一点“价值空间”都不想留给对方。注重长期主义的人，拼命退让“价值空间”，想要“价值空间”最大化留给对方。注重眼前利益的人，一时赚得盘满钵满，未来路却越走越窄。注重长期主义的人，一时利润不尽人意， 未来路却越走越宽。<a href="https://zhuanlan.zhihu.com/p/351748364" target="_blank" rel="noreferrer">^24</a></p><h4 id="长期视角和容错" tabindex="-1">长期视角和容错 <a class="header-anchor" href="#长期视角和容错" aria-label="Permalink to &quot;长期视角和容错&quot;">​</a></h4><p>伟大的企业都明白，一切商业的起点，都是消费者获益。但是他们也明白，从消费者获益，到自己赚钱之间，也就是从这个起点到终点之间，是个先后关系，常常有一个时间差。</p><p>那么，用什么填补这个时间差？只有用企业家的长期主义。</p><p>亚马逊创始人贝佐斯曾在演讲中提到：人们经常问未来 10 年什么会被改变，却从来没人问：未来 10 年，什么不会变。<a href="https://mp.weixin.qq.com/s?__biz=Mzg2MTEwNDQxMg==&amp;mid=2247483696&amp;idx=1&amp;sn=5d7c4af6c3228a7c1105898ce97d63c0&amp;chksm=ce1d7143f96af8555b06fc18df4e021b6e6967cc0f30cbd4c7dddba1d32f1cbd1eecc9b5e18c&amp;cur_album_id=1508906417947197443&amp;scene=189#rd" target="_blank" rel="noreferrer">^19</a></p><p>长期视角和容错：如果你想抓住下一个十年中的大机会，那最好持有一个十年的长期视角，没人能保证一次命中，但连续出手三次的命中率就高多了。简单计划可以是这样：看到一个可能的大机会，及时加入它，用一两年好好干好好学，在这个过程中评估它的市场需求、组织问题、政策和竞争问题，一两年够你形成较有效判断了，如果判断行就继续全力投入；如果判断不行，就选择下一个可能的大机会，再用一两年去形成有效判断；如是循环，做好十年三次选择的心理准备，确定机会后就全力投入，注意保持成长和共赢。<a href="https://mp.weixin.qq.com/s/etrsGOjfK1OXJpOOhSbbug" target="_blank" rel="noreferrer">^18</a></p><p>正如著名投资专家本杰明·格雷厄姆所说：“短期来看，股票市场就是个投票器；但长期来看，它是个称重机。” 长期主义，就是扔掉投票器，踏上称重机。<a href="https://www.163.com/dy/article/G8GK002B051181GK.html" target="_blank" rel="noreferrer">^23</a></p><p><img src="'+h+'" alt="价格成本结构循环"></p><p>如果你做一件事，把眼光放到未来三年，和你同台竞技的人很多；但如果你的目光能放到未来七年，那么可以和你竞争的人就很少了。因为很少有公司愿意做那么长远的打算。</p><h4 id="选择最能为人类福利而劳动的职业" tabindex="-1">选择最能为人类福利而劳动的职业 <a class="header-anchor" href="#选择最能为人类福利而劳动的职业" aria-label="Permalink to &quot;选择最能为人类福利而劳动的职业&quot;">​</a></h4><p>“如果我们选择了最能为人类福利而劳动的职业，那么重担就不能把我们压倒，因为这是为人类而献身。那时我们所感受到的就不是可怜的、有限的、自私的乐趣，我们的幸福将属于千百万人，我们的事业将默默地、但永恒发挥作用地存在下去，而面对我们的骨灰，高尚的人们将洒下热泪。”<a href="https://zhuanlan.zhihu.com/p/49507112" target="_blank" rel="noreferrer">^21</a></p><h3 id="什么是知识体系" tabindex="-1">什么是知识体系 <a class="header-anchor" href="#什么是知识体系" aria-label="Permalink to &quot;什么是知识体系&quot;">​</a></h3><h4 id="信息与知识" tabindex="-1">信息与知识 <a class="header-anchor" href="#信息与知识" aria-label="Permalink to &quot;信息与知识&quot;">​</a></h4><p>定义：</p><ul><li>什么叫信息，能够消除不确定性的数据就是信息。<a href="https://www.zhihu.com/question/443911275" target="_blank" rel="noreferrer">^11</a></li><li>知识是人类认识的成果,它是在实践的基础上产生又经过实践检验的对客观实际的反映。只有用人类创造的一切财富的知识来丰富自己的头脑。才能成为共产主义者。<a href="https://www.bilibili.com/read/cv13249490/?from=readlist" target="_blank" rel="noreferrer">^27</a></li></ul><p>信息与知识的区别：</p><ol><li>信息的理解是容易的，知识的积累是艰难的，信息的获取可以在刹那之间完成，知识的掌握则需要漫长的付出。小铁匠想了解淬火的温度，只消把手插入水桶感受一下，立刻就能明白，并不需要多打十年铁才具备资格。黑医生通过“信息套利”提供治疗方案时，病人并不需要读七八年医科才知道他是不是信息套利，只要别的医生提出，病人马上就能怀疑。而病人要想真正明白治疗方案是否合理，就需要读好几年医科，这就是知识而不是信息了。</li><li>信息的变现是容易的，而且往往独立；知识的回报则相对漫长，并且往往需要和其他要素结合。一个人听到内部消息去买股票，马上就能获利；而一个人读到博士，想找份合适的工作，还并不总是很容易。而博士拿到的薪水，往往不如内部消息的套利。</li><li>信息在事后是不值钱的，一旦交易达成，信息的价值几乎下降为零。而知识的价值，一般不会随时间而贬损，还会随知识积累而攀升。<a href="https://zhuanlan.zhihu.com/p/409630686" target="_blank" rel="noreferrer">^26</a></li></ol><h4 id="知识体系" tabindex="-1">知识体系 <a class="header-anchor" href="#知识体系" aria-label="Permalink to &quot;知识体系&quot;">​</a></h4><p>知识体系有三个特性：目标性、体系性以及抽象性，多使用逻辑树进行构建。<a href="http://www.woshipm.com/zhichang/4156203.html" target="_blank" rel="noreferrer">^10</a></p><ul><li>目标是指方向聚焦，体系有重点。体系是指结构完整、层次分明，前2层分支的平衡性越好，归纳程度也越强。</li><li>而抽象则是知识体系是知识从具体到抽象的表现，呈现了知识的特征或本质。</li><li>再进一层，什么是好的知识体系呢？除了上述所描述的有目标、够全面、抽象程度高，还有一点则是知识体系应该是相互独立但非无限穷尽的。</li></ul><p>有的知识仅须停留在知道，有的则需要运用并且创新。</p><p>把你已经知道的东西梳理一遍。如何梳理呢？以你能够说出某个知识点的影响因素，以及它对其他事物的影响为准。顺着这样的知识点捋一遍，这个网络就是你已经构建完成的知识网络<a href="https://www.zhihu.com/market/paid_magazine/1153593677761941504/section/1153593764286263296" target="_blank" rel="noreferrer">^16</a>。</p><h3 id="用技能分工代替职业分工" tabindex="-1">用技能分工代替职业分工 <a class="header-anchor" href="#用技能分工代替职业分工" aria-label="Permalink to &quot;用技能分工代替职业分工&quot;">​</a></h3><p>要每一个项目都组建一支产品、交互、设计、前端、后台、运营的团队肯定是不现实。我的想法就是团队的每个人经可能多的学习技能，走全栈型路线。在王者里面每个英雄<strong>可以带三个技能</strong>，如果有人能带五个技能，基本上可以一个顶两个用了。产品、交互还有运营基本上可以<strong>合并为一个人</strong>来统筹负责，技术部分<strong>用跨平台的解决方案简化为一到两个人来负责</strong>。Full Stack后眼界和见识提高<a href="https://www.zhihu.com/question/22613861/answer/34122925" target="_blank" rel="noreferrer">^12</a>，这样<strong>大幅简化了人员的沟通成本</strong>，缩减了项目切换过程中所需要的冷却值。而且从市场的反馈到产品的迭代更新间的<strong>反射弧更加的快速</strong>。 <a href="http://dyin.tech/" target="_blank" rel="noreferrer">^2</a></p><p>因为当单个工人能够较以前提供更多的劳动，则可变资本增大时，资本家无须招收更多的工人，就可以利用现有工人来推动更多的劳动。可变资本相对减少了，但就业人数减少得更多。<a href="http://www.doc88.com/p-5738403457973.html" target="_blank" rel="noreferrer">^22</a></p><h2 id="全栈产品经理" tabindex="-1">全栈产品经理 <a class="header-anchor" href="#全栈产品经理" aria-label="Permalink to &quot;全栈产品经理&quot;">​</a></h2><p>全栈产品经理必须完全理解/了解自己业务系统，从底层基础架构，到数据中间件，到API逻辑，到 Web 和 Mobile 实现，到 UX 和 UI，到产品逻辑，到部署和发布计划的制定。<a href="https://www.zhihu.com/question/22613861/answer/118658853" target="_blank" rel="noreferrer">^13</a></p><p><img src="'+i+'" alt="“全栈产品经理”的技能树"></p><h2 id="减人加速" tabindex="-1">减人加速 <a class="header-anchor" href="#减人加速" aria-label="Permalink to &quot;减人加速&quot;">​</a></h2><p>须知人数越少，沟通成本越低，执行效率越高。需要兼任PM/交互/QA，并且主持搭建内容框架。如果给我再配一两个交互设计师，一两个QA，内容框架也交出去，再和他们反复沟通确认，我的速度反而被拉了下来。这不仅苛求个人能力，也要求你在大包大揽时，还能接受其中的粗活笨活。如果把我手上各种杂活剥离出去，起码能设3个岗位——并且速度拖慢50%。技术研发也是如此，减人才能提速。又要减人又要代码能力，大牛就得分担杂活。<a href="https://zhuanlan.zhihu.com/p/291532809" target="_blank" rel="noreferrer">^15</a>本质是，“高内聚低耦合”的设计。</p><p>这是否导致更多人失业？也不一定，TODO:</p><h2 id="ai商业化逻辑" tabindex="-1">AI商业化逻辑 <a class="header-anchor" href="#ai商业化逻辑" aria-label="Permalink to &quot;AI商业化逻辑&quot;">​</a></h2><p>2017年AI人才结构失衡。特别是发论文的人和做产品或解决方案研发的人，比例严重倒挂。 <a href="https://www.zhihu.com/question/279550559" target="_blank" rel="noreferrer">^4</a></p><p>当时最好的AI技术人员更愿意在大学里搞学术，或在企业研究院里发论文，或在创业公司拿着高薪担任首席科学家之类的职位，但AI商业化落地亟需的AI应用开发人员、AI架构设计人员、AI产品和解决方案设计人员等，人才市场上几乎是空白。规模巨大的计算机或相关专业毕业生、有经验的前后端工程师、架构设计师、产品经理的人群中，当时懂得AI特别是懂得AI商业化逻辑的人，真是少之又少。</p><p>“我们认为，AI商业化的最佳途径对百度来说，就是平台化、生态化。一个开放的生态最具活力最有竞争力。”陆奇说道。<a href="https://ai.baidu.com/forum/topic/show/492818" target="_blank" rel="noreferrer">^5</a></p><h2 id="功能点" tabindex="-1">功能点： <a class="header-anchor" href="#功能点" aria-label="Permalink to &quot;功能点：&quot;">​</a></h2><h3 id="常用" tabindex="-1">常用 <a class="header-anchor" href="#常用" aria-label="Permalink to &quot;常用&quot;">​</a></h3><p>标签： :lable:、:ref:</p><p><a href="https://www.bobinsun.cn/blog/2019/03/29/Markdown-Diabolic-tricks/" target="_blank" rel="noreferrer">^Markdown用法之-奇技淫巧</a></p><h3 id="todo" tabindex="-1">TODO： <a class="header-anchor" href="#todo" aria-label="Permalink to &quot;TODO：&quot;">​</a></h3><p>google analysis.</p><blockquote><p>（本节目录见左侧导航）</p></blockquote><blockquote><p>（本节目录见左侧导航）</p></blockquote><blockquote><p>（本节目录见左侧导航）</p></blockquote>',68)])])}const w=e(n,[["render",p]]);export{u as __pageData,w as default};
